 en: {
 skip:'Skip to content',navOverview:'Mobility lab',navSystem:'How it works',navRoadmap:'Execution plan',eyebrow:'See the flow. Anticipate the queue.',hero:'A city in motion.<br><span>A smarter decision.</span>',heroCopy:'A digital twin that tests the decision before it reaches the road.\nExplore how intersection data becomes smoother movement.',prototype:'Interactive concept demo',honesty:'Illustrative data. No connection to real cameras or the SUMO engine.',exploreSystem:'Explore the architecture',labTitle:'An intersection, in focus',simulationLabel:'INTERSECTION A · DEMO ENVIRONMENT',scenarioTitle:'Choose a scenario',congestion:'Sudden congestion',congestionSub:'When intersection demand rises',ambulance:'Emergency priority',ambulanceSub:'Make room. Keep it safe.',offline:'Cloud outage',offlineSub:'Keep decisions local',demand:'Traffic demand',light:'Low',heavy:'High',whatHappens:'WHAT HAPPENS',run:'Run scenario',pause:'Pause scenario',resume:'Resume scenario',replay:'Replay scenario',ready:'Ready to explore',running:'Scenario running',paused:'Scenario paused',finished:'Scenario complete',reset:'Reset ↺',digitalTwin:'Digital twin',optimized:'Adaptive control',baseline:'Fixed timing',mapReady:'Waiting for the scenario',flow:'Vehicles',queue:'Waiting area',recommended:'Suggested route',pauseMotion:'Pause motion Ⅱ',resumeMotion:'Resume motion ▷',waitTime:'Average waiting time',seconds:'sec',vsBaseline:'Compared with fixed timing',queueLength:'Queue length',vehicles:'vehicles',northApproach:'North approach',illustrative:'Illustrative value',emergencyTime:'Emergency crossing',priority:'Safe priority',edgeState:'Edge processing',localActive:'Local & active',cloudConnected:'Simulated cloud connection',cloudOffline:'Cloud offline · edge active',decisionTitle:'From observation to action',stepObserve:'Observe',stepPredict:'Test options',stepGuard:'Safety check',stepAct:'Recommend',comparisonTitle:'Same intersection. Different decision.',sample:'ILLUSTRATIVE',chartCaption:'Average delay across all approaches, using identical demand and model time.',methodTitle:'What does this demo actually show?',methodBody:'This interactive interface explains the proposed FlowTwin AI experience. It is not a field test or a measured result. Vehicle motion and values come from an illustrative browser model with separated signal phases and following gaps. Comparisons cover every approach and upstream queues. Values are not calibrated to reality; EcoTwin assumptions appear below its chart. Proving the impact requires YOLO, ByteTrack, SUMO and MQTT integration, followed by a fixed-time baseline comparison across at least 10 random seeds and 3 demand profiles, with confidence intervals.',footer:'From watching congestion to anticipating it.',idleEvent:'Choose a scenario and run it to follow the decision sequence.',baselineEvent:'Comparison mode: a fixed signal cycle without an adaptive recommendation.',baselineMap:'Fixed timing · no adaptive optimization',completedEvent:'Illustrative sequence complete. Compare the decision with fixed timing.',scenarioDescriptions:{congestion:'Demand rises from the north. The twin tests a longer green phase to reduce the queue before recommending it.',ambulance:'An ambulance approaches from the west. Intersection clearance is checked before priority is recommended.',offline:'The cloud link drops. Processing continues at the edge, with events buffered for later synchronization.'},events:{congestion:['A rise in traffic demand is detected on the north approach.','The twin compares fixed timing with a longer green phase.','Minimum green time and conflicting movements are checked.','Recommendation: extend the north phase to reduce the queue.'],ambulance:['An ambulance marker is detected on the west approach.','The twin tests clearing the route ahead of the ambulance.','A clearance interval is applied before priority is granted.','Recommendation: open east–west, then return to the normal cycle.'],offline:['A cloud connection loss is simulated.','Local evaluation continues with illustrative input data.','Local safety rules remain active.','Decision stays local. Events are notionally buffered for synchronization.']},mapEvents:{congestion:['North queue detected','Testing signal options','Checking safety','Longer green recommended'],ambulance:['Ambulance detected','Planning priority route','Safe clearance interval','East–west priority'],offline:['Cloud disconnected','Edge processing continues','Safety rules remain active','Ready for later synchronization']},systemEyebrow:'02 / THE PROPOSED ARCHITECTURE',systemTitle:'Test the possibility.<br><span>Then change the signal.</span>',systemCopy:'One decision loop connects edge perception to a digital twin. Options are tested first, then a safety guard checks the recommendation before it reaches the miniature intersection.',loopTitle:'From camera to intersection',loopMeta:'Target architecture · in development',pipeline:[['01','Perceive','The camera captures the scene. Edge processing detects and tracks vehicles and estimates queues.','YOLO / ByteTrack'],['02','Understand','Events and counts replace continuous video, with local buffering during an outage.','MQTT / Edge buffer'],['03','Test','The twin receives traffic demand and compares signal decisions before proposing a change.','SUMO / TraCI'],['04','Verify','A safety guard enforces minimum green times, clearance intervals and conflict rules.','Safety guard'],['05','Recommend','The dashboard shows the recommendation, while an ESP32 drives the miniature signal LEDs.','FastAPI / ESP32']],buildTitle:'What this cycle will deliver',buildItems:[['Measurable edge perception','Vehicle counts, queue estimates and ambulance markers using the miniature model’s data.'],['A twin linked to demand','Feed live counts into SUMO through TraCI and replay three recorded scenarios.'],['Decisions that survive an outage','A heuristic optimizer first, with a local MQTT broker and independent safety rules.']],proofTitle:'How we will prove it works',proofItems:[['A reproducible baseline','A fair comparison with fixed signals, using at least 10 random seeds and 3 demand profiles.'],['Evidence, attached to every number','Trace each claim to an experiment log and report confidence intervals and measurement limits.'],['Safety is a hard gate','Zero safety violations before the control loop is demonstrated on the miniature model.']],targetsTitle:'Validation targets',targetsNote:'Project goals — not proven results',targets:[['Average waiting time','−20%','Compared with the fixed-time baseline'],['Emergency crossing time','−30%','Subject to the safety constraints'],['Bus regularity','+15%','A should-have, if time permits']],scopeTitle:'Prototype boundaries',scopeBody:'One miniature intersection and recorded video. No real city camera integration or control of public traffic signals. Reinforcement learning, extra sensors and emissions estimates are optional upgrades.',roadmapEyebrow:'03 / THE EXECUTION PLAN',roadmapTitle:'From the first frame.<br><span>To a credible demonstration.</span>',roadmapCopy:'Six milestones to build and validate the complete loop. The plan assumes ten weeks; the competition date and hardware availability still need confirmation.',milestonesTitle:'The build sequence',allNotStarted:'6 milestones · all not started',weeksAssumption:'10 weeks — planning assumption',notStarted:'Not started',weeks:'Weeks',owner:'Owner',deliverables:'Deliverables',gate:'Validation gate',milestones:[['M1','Foundations & data contracts','1–2','Integration lead + all leads',['Repository, CI, documented MQTT and JSON schemas','Measurement protocol and fixed-time SUMO baseline','Hardware orders and a draft demo runbook'],'Reproduce the baseline across 10 seeds, with all interfaces documented and variance ≤5%.'],['M2','Edge perception pipeline','2–4','Computer vision + hardware',['YOLO and ByteTrack detection and tracking','Queue estimates, bus and ambulance markers','Test video set and offline buffering'],'One hour without a crash; count error ≤10%, ≥15 FPS, and event latency under one second.'],['M3','Digital twin & forecasting','3–6','Simulation + machine learning',['SUMO intersection with TraCI demand input','Forecasting model, starting with XGBoost','Evaluation notebook and three replayable scenarios'],'Queues within ±15% of observations; 5-minute MAPE ≤15% and better than persistence.'],['M4','Optimization & closed loop','5–8','Optimization + hardware + backend',['Heuristic optimizer and emergency priority','Safety guard and ESP32 miniature signal control','RL go/no-go decision at the end of week 7'],'Zero safety violations; assess waiting and emergency targets across ≥10 seeds and 3 demand profiles.'],['M5','Dashboard & integration','6–9','Dashboard + backend',['Live state, forecasts, alerts and before/after comparison','Selector for the three demo scenes','Full integration and a cloud-disconnection test'],'End-to-end operation without cloud; alerts under 2 seconds and ≥80% less data than continuous video, measured.'],['M6','Validation & demo readiness','9–10','Integration lead + team',['Results report with confidence intervals','Three rehearsals and a backup recording','Pitch deck and one-page technical brief'],'Each scene passes 10 consecutive runs. Every claimed number is traceable to an experiment.']],riskTitle:'The risks have a plan, too',risks:[['Performance targets are missed','Lock the baseline early. Keep the heuristic optimizer as the primary path and report actual measurements transparently.'],['Detection struggles on the miniature','Train on captured model images and use a visual or MQTT ambulance marker instead of assuming pretrained detection will work.'],['Hardware or demo-day failure','Start on a laptop, run a local broker and prepare a recorded backup of the demonstration.']],weekOneTitle:'The first move',weekOneBody:'Confirm the competition date and demo conditions, order hardware, freeze schemas and measurement protocols, and name an owner for every milestone.',download:'Download technical brief',downloadHint:'Markdown · scope, targets and limitations',downloadDone:'Your file is ready to download.'
 }
