const state={lang:'ar',scenario:'congestion',mode:'optimized',demand:70,started:false,running:false,complete:false,motionPaused:matchMedia('(prefers-reduced-motion: reduce)').matches};
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
const t=k=>copy[state.lang][k];
function renderMap(){
 $('#map').innerHTML=IntersectionMap.svg(state.lang);
 window.trafficUI?.mount();
}

function updateMetrics(){window.trafficUI?.paint();}
function updateStage(){
 $('#scenario-description').textContent=t('scenarioDescriptions')[state.scenario];
 $('#run-label').textContent=t(state.running?'pause':state.complete?'replay':state.started?'resume':'run');
 $('#run-icon').textContent=state.running?'Ⅱ':'↗';
 $('#run-status').textContent=t(state.running?'running':state.complete?'finished':state.started?'paused':'ready');
 $('#motion').textContent=t(state.motionPaused?'resumeMotion':'pauseMotion');$('#motion').setAttribute('aria-pressed',String(state.motionPaused));
 $('#map').classList.toggle('motion-paused',state.motionPaused||(!state.running&&state.started&&!state.complete));
 $('#map').classList.toggle('ambulance-mode',state.scenario==='ambulance');$('#map').classList.toggle('offline-mode',state.scenario==='offline'&&state.started);$('#map').classList.toggle('baseline-mode',state.mode==='baseline');
 window.trafficUI?.sync();
 updateMetrics();
}
function resetRun(){window.trafficUI?.reset();state.started=false;state.running=false;state.complete=false;updateStage();}
function toggleRun(){window.trafficUI?.toggle();}
function listItems(items){return `<ul class="lined-list">${items.map(([title,text],i)=>`<li><span>0${i+1}</span><div><strong>${title}</strong><p>${text}</p></div></li>`).join('')}</ul>`;}
function renderSystem(){
 $('#system').innerHTML=`<div class="page-heading"><div class="eyebrow"><span class="tiny-line"></span>${t('systemEyebrow')}</div><h1 id="system-title">${t('systemTitle')}</h1><p>${t('systemCopy')}</p></div><section class="architecture"><div><h2>${t('loopTitle')}</h2><span class="quiet">${t('loopMeta')}</span></div><div class="pipeline">${t('pipeline').map(([n,title,p,tech])=>`<div class="pipeline-step"><span class="mono">${n}</span><h3>${title}</h3><p>${p}</p><p class="pipeline-tech mono">${tech}</p></div>`).join('')}</div></section><div class="system-details"><section><h2>${t('buildTitle')}</h2>${listItems(t('buildItems'))}</section><section><h2>${t('proofTitle')}</h2>${listItems(t('proofItems'))}</section></div><div class="workspace-heading"><h2>${t('targetsTitle')}</h2><span class="quiet">${t('targetsNote')}</span></div><div class="target-grid">${t('targets').map(([a,b,c])=>`<div class="target"><span>${a}</span><b>${b}</b><p>${c}</p></div>`).join('')}</div><div class="scope-strip"><h3>${t('scopeTitle')}</h3><p>${t('scopeBody')}</p></div>`;
}
function renderRoadmap(){
 const openIds=$$('.milestone[open]').map(x=>x.dataset.id);
 $('#roadmap').innerHTML=`<div class="page-heading"><div class="eyebrow"><span class="tiny-line"></span>${t('roadmapEyebrow')}</div><h1 id="roadmap-title">${t('roadmapTitle')}</h1><p>${t('roadmapCopy')}</p></div><div class="roadmap-topline"><h2>${t('milestonesTitle')}</h2><div class="roadmap-note"><span>${t('allNotStarted')}</span><span>${t('weeksAssumption')}</span></div></div><div class="timeline">${t('milestones').map(([id,title,weeks,owner,items,gate])=>`<details class="milestone" data-id="${id}" ${openIds.includes(id)?'open':''}><summary><span class="mono">${id}</span><h3>${title}</h3><span class="week">${t('weeks')} <bdi>${weeks}</bdi></span><span class="not-started">${t('notStarted')}</span><span class="expand" aria-hidden="true">+</span></summary><div class="milestone-body"><div><h4>${t('deliverables')}</h4><ul>${items.map(x=>`<li>${x}</li>`).join('')}</ul><h4>${t('owner')}: ${owner}</h4></div><div class="gate"><strong>${t('gate')}</strong><p>${gate}</p></div></div></details>`).join('')}</div><div class="scope-strip"><h3>${t('weekOneTitle')}</h3><p>${t('weekOneBody')}</p></div><section class="roadmap-risk"><h2>${t('riskTitle')}</h2><div class="risk-grid">${t('risks').map(([title,p])=>`<div class="risk-item"><h3>${title}</h3><p>${p}</p></div>`).join('')}</div></section><div class="roadmap-actions"><button class="secondary-button" id="download"><span>${t('download')}</span><span aria-hidden="true">↓</span></button><span id="export-status" class="export-status" role="status">${t('downloadHint')}</span></div>`;
 $('#download').addEventListener('click',downloadBrief);
}
function downloadBrief(){
 const text=`# FlowTwin AI — ${t('download')}\n\n${t('roadmapCopy')}\n\n## ${t('scopeTitle')}\n${t('scopeBody')}\n\n## ${t('targetsTitle')}\n${t('targetsNote')}\n${t('targets').map(([a,b,c])=>`- ${a}: ${b} — ${c}`).join('\n')}\n\n## ${t('loopTitle')}\n${t('pipeline').map(([n,title,p,tech])=>`${n}. ${title}: ${p} (${tech})`).join('\n')}\n\n## ${t('milestonesTitle')}\n${t('milestones').map(([id,title,weeks,owner,items,gate])=>`\n### ${id} — ${title}\n${t('weeks')}: ${weeks} | ${t('owner')}: ${owner} | ${t('notStarted')}\n${items.map(x=>'- '+x).join('\n')}\n${t('gate')}: ${gate}`).join('\n')}\n\n## ${t('methodTitle')}\n${t('methodBody')}\n`;
 const url=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/markdown;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`FlowTwin-technical-brief-${state.lang}.md`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#export-status').textContent=t('downloadDone');
}
function translate(){document.documentElement.lang=state.lang;document.documentElement.dir=state.lang==='ar'?'rtl':'ltr';document.title=state.lang==='ar'?'FlowTwin AI — مختبر الحركة':'FlowTwin AI — Mobility Lab';$$('[data-i18n]').forEach(e=>e.textContent=t(e.dataset.i18n));$$('[data-i18n-html]').forEach(e=>e.innerHTML=t(e.dataset.i18nHtml));$('#language').innerHTML=state.lang==='ar'?'EN <span aria-hidden="true">↗</span>':'عربي <span aria-hidden="true">↗</span>';$('#language').setAttribute('aria-label',state.lang==='ar'?'Switch to English':'التبديل إلى العربية');$('.navigation').setAttribute('aria-label',state.lang==='ar'?'التنقل الرئيسي':'Main navigation');renderSystem();renderRoadmap();renderMap();updateStage();}
function route(){if(location.hash==='#main'){$('#main').focus();return}const requested=['overview','ecotwin','safecross','system','roadmap'].includes(location.hash.slice(1))?location.hash.slice(1):'overview';const page=requested==='ecotwin'?'overview':requested;$$('.page').forEach(e=>{e.hidden=e.id!==page;e.classList.toggle('active-page',e.id===page)});$$('[data-page]').forEach(e=>{const active=e.dataset.page===requested;e.classList.toggle('active',active);if(active)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current')});if(page!=='overview'&&state.running){state.running=false;updateStage()}if(requested==='ecotwin')$('#ecotwin')?.scrollIntoView({block:'start',behavior:'instant'});else window.scrollTo({top:0,behavior:'instant'});}
$$('.scenario').forEach(button=>button.addEventListener('click',()=>{state.scenario=button.dataset.scenario;$$('.scenario').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});resetRun()}));
$$('[data-mode]').forEach(button=>button.addEventListener('click',()=>{state.mode=button.dataset.mode;$$('[data-mode]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});updateStage()}));
$('#demand').addEventListener('input',e=>{state.demand=Number(e.target.value);resetRun()});
$('#run').addEventListener('click',toggleRun);$('#reset').addEventListener('click',resetRun);$('#language').addEventListener('click',()=>{state.lang=state.lang==='ar'?'en':'ar';translate();try{localStorage.setItem('flowtwin-language',state.lang)}catch{}});window.addEventListener('hashchange',route);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.running){state.running=false;updateStage()}});
try{const lang=localStorage.getItem('flowtwin-language');if(['ar','en'].includes(lang))state.lang=lang}catch{}
translate();route();

